import type { BuildRESTFunction, MaybeContext, RESTFunctionDescriptor } from '@wix/sdk-types';
/**
 * The generic SDK 2.0 method runtime: every method of a generated v2 SDK
 * package is one `restMethod(verb, protoPath, resolver)` const, so no
 * per-method logic is ever generated and all packages share this single
 * implementation. Kept in its own subpath so a bundle pays for it once,
 * however many SDK packages an app uses.
 */
export type Verb = 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
/** A generated per-service url resolver (the http lane's only export). */
export type UrlResolver = (opts: {
    protoPath: string;
    data?: object;
    host: string;
}) => string;
/**
 * The type of one SDK module method with call shape `Signature`: callable
 * directly under a Wix context (auto-injected client), and consumable by
 * `createClient({ modules })`, which sees the RESTFunctionDescriptor side.
 */
export type ModuleMethod<Signature extends (request?: any) => Promise<any>> = MaybeContext<BuildRESTFunction<RESTFunctionDescriptor<Signature>> & RESTFunctionDescriptor<Signature>>;
/**
 * The single shared method factory: binds the per-method constants (verb +
 * proto path) and the service's url resolver as an SDK method. The raw JSON
 * response data is returned — no transformations.
 *
 * `postFallbackPath` is set only on GET methods whose service declares an
 * explicit POST mapping for the same RPC: the client switches to that POST
 * past 4000 chars of query string (the long-url fallback). GETs without a
 * declared POST route never fall back — a blind same-route POST could hit a
 * different RPC.
 * @param verb - The HTTP verb of the method's chosen mapping.
 * @param protoPath - The method's proto route template.
 * @param resolveServiceUrl - The generated resolver of the method's service.
 * @param postFallbackPath - The declared POST route for long GET urls, if any.
 * @returns The bound SDK method.
 */
export declare function restMethod<Signature extends (request?: any) => Promise<any>>(verb: Verb, protoPath: string, resolveServiceUrl: UrlResolver, postFallbackPath?: string): ModuleMethod<Signature>;
